// ==================== ADVANCED TECHNICAL INDICATORS ====================

function calculateEMA(prices, period) {
    if (prices.length < period) return null;
    const k = 2 / (period + 1);
    let ema = prices.slice(0, period).reduce((a, b) => a + b, 0) / period;
    for (let i = period; i < prices.length; i++) {
        ema = (prices[i] * k) + (ema * (1 - k));
    }
    return ema;
}

function calculateEMAArray(prices, period) {
    if (prices.length < period) return [];
    const k = 2 / (period + 1);
    const emaArray = [];
    let ema = prices.slice(0, period).reduce((a, b) => a + b, 0) / period;
    emaArray.push(ema);
    for (let i = period; i < prices.length; i++) {
        ema = (prices[i] * k) + (ema * (1 - k));
        emaArray.push(ema);
    }
    return emaArray;
}

function calculateRSI(prices, period = 14) {
    if (prices.length < period + 1) return 50;
    let gains = 0, losses = 0;
    for (let i = prices.length - period; i < prices.length; i++) {
        const change = prices[i] - prices[i - 1];
        if (change > 0) gains += change;
        else losses += Math.abs(change);
    }
    const avgGain = gains / period;
    const avgLoss = losses / period;
    const rs = avgGain / (avgLoss || 0.001);
    return 100 - (100 / (1 + rs));
}

function calculateStochastic(bars, period = 14, smoothK = 3, smoothD = 3) {
    if (bars.length < period) return { k: 50, d: 50 };

    const highs = bars.slice(-period).map(b => b.h);
    const lows = bars.slice(-period).map(b => b.l);
    const closes = bars.slice(-period).map(b => b.c);

    const kValues = [];
    for (let i = 0; i < closes.length; i++) {
        const lowestLow = Math.min(...lows.slice(Math.max(0, i - period + 1), i + 1));
        const highestHigh = Math.max(...highs.slice(Math.max(0, i - period + 1), i + 1));
        const k = highestHigh === lowestLow ? 50 : ((closes[i] - lowestLow) / (highestHigh - lowestLow)) * 100;
        kValues.push(k);
    }

    // Smooth %K
    const smoothedK = kValues.slice(-smoothK).reduce((a, b) => a + b, 0) / smoothK;

    // %D is SMA of %K
    const dValues = [];
    for (let i = smoothK - 1; i < kValues.length; i++) {
        const d = kValues.slice(i - smoothK + 1, i + 1).reduce((a, b) => a + b, 0) / smoothK;
        dValues.push(d);
    }
    const smoothedD = dValues.length > 0 ? dValues[dValues.length - 1] : 50;

    return { k: smoothedK, d: smoothedD };
}

function calculateCCI(bars, period = 20) {
    if (bars.length < period) return 0;

    const typicalPrices = bars.map(b => (b.h + b.l + b.c) / 3);
    const sma = typicalPrices.slice(-period).reduce((a, b) => a + b, 0) / period;
    const meanDeviation = typicalPrices.slice(-period)
        .reduce((sum, tp) => sum + Math.abs(tp - sma), 0) / period;

    const currentTP = typicalPrices[typicalPrices.length - 1];
    return (currentTP - sma) / (0.015 * meanDeviation);
}

function calculateOBV(bars) {
    if (bars.length < 2) return 0;
    let obv = 0;
    for (let i = 1; i < bars.length; i++) {
        if (bars[i].c > bars[i - 1].c) {
            obv += bars[i].v;
        } else if (bars[i].c < bars[i - 1].c) {
            obv -= bars[i].v;
        }
    }
    return obv;
}

function calculateADX(bars, period = 14) {
    if (bars.length < period * 2) return { adx: 0, plusDI: 0, minusDI: 0 };

    const tr = [], dmPlus = [], dmMinus = [];

    for (let i = 1; i < bars.length; i++) {
        const prev = bars[i - 1];
        const curr = bars[i];
        tr.push(Math.max(curr.h - curr.l, Math.abs(curr.h - prev.c), Math.abs(curr.l - prev.c)));
        const upMove = curr.h - prev.h;
        const downMove = prev.l - curr.l;
        dmPlus.push(upMove > downMove && upMove > 0 ? upMove : 0);
        dmMinus.push(downMove > upMove && downMove > 0 ? downMove : 0);
    }

    let smtr = tr.slice(0, period).reduce((sum, val) => sum + val, 0);
    let smPlus = dmPlus.slice(0, period).reduce((sum, val) => sum + val, 0);
    let smMinus = dmMinus.slice(0, period).reduce((sum, val) => sum + val, 0);

    const diPlus = [], diMinus = [], dx = [];

    diPlus[0] = (smPlus / smtr) * 100;
    diMinus[0] = (smMinus / smtr) * 100;
    dx[0] = (Math.abs(diPlus[0] - diMinus[0]) / (diPlus[0] + diMinus[0])) * 100;

    for (let i = period; i < tr.length; i++) {
        smtr = smtr - (smtr / period) + tr[i];
        smPlus = smPlus - (smPlus / period) + dmPlus[i];
        smMinus = smMinus - (smMinus / period) + dmMinus[i];

        const currentDIPlus = (smPlus / smtr) * 100;
        const currentDIMinus = (smMinus / smtr) * 100;
        diPlus.push(currentDIPlus);
        diMinus.push(currentDIMinus);

        const diDiff = Math.abs(currentDIPlus - currentDIMinus);
        const diSum = currentDIPlus + currentDIMinus;
        dx.push(diSum > 0 ? (diDiff / diSum) * 100 : 0);
    }

    let adx = dx.slice(0, period).reduce((sum, val) => sum + val, 0) / period;
    for (let i = period; i < dx.length; i++) {
        adx = (adx * (period - 1) + dx[i]) / period;
    }

    return {
        adx: adx,
        plusDI: diPlus[diPlus.length - 1] || 0,
        minusDI: diMinus[diMinus.length - 1] || 0
    };
}

function calculateMACD(prices, shortPeriod = 12, longPeriod = 26, signalPeriod = 9) {
    if (prices.length < longPeriod + signalPeriod) return null;

    const shortEMA = calculateEMAArray(prices, shortPeriod);
    const longEMA = calculateEMAArray(prices, longPeriod);

    // Align EMAs
    const offset = longPeriod - shortPeriod;
    const macdLine = shortEMA.slice(offset).map((val, i) => val - longEMA[i]);

    if (macdLine.length < signalPeriod) return null;

    const signalLine = calculateEMAArray(macdLine, signalPeriod);

    if (!signalLine || signalLine.length === 0) return null;

    const currentMACD = macdLine[macdLine.length - 1];
    const currentSignal = signalLine[signalLine.length - 1];
    const histogram = currentMACD - currentSignal;
    const prevHistogram = macdLine.length > 1 ? macdLine[macdLine.length - 2] - (signalLine.length > 1 ? signalLine[signalLine.length - 2] : currentSignal) : 0;

    return {
        macd: currentMACD,
        signal: currentSignal,
        histogram: histogram,
        prevHistogram: prevHistogram
    };
}

// ==================== SUPPORT/RESISTANCE DETECTION ====================

function findSupportResistance(bars, lookback = 50) {
    if (bars.length < lookback) return { support: [], resistance: [] };

    const recentBars = bars.slice(-lookback);
    const highs = recentBars.map(b => b.h);
    const lows = recentBars.map(b => b.l);

    const support = [];
    const resistance = [];

    // Find pivot points (local extrema)
    for (let i = 2; i < recentBars.length - 2; i++) {
        // Pivot high (resistance)
        if (highs[i] > highs[i-1] && highs[i] > highs[i-2] &&
            highs[i] > highs[i+1] && highs[i] > highs[i+2]) {
            resistance.push(highs[i]);
        }

        // Pivot low (support)
        if (lows[i] < lows[i-1] && lows[i] < lows[i-2] &&
            lows[i] < lows[i+1] && lows[i] < lows[i+2]) {
            support.push(lows[i]);
        }
    }

    // Cluster nearby levels (within 1%)
    const clusterLevels = (levels) => {
        if (levels.length === 0) return [];
        levels.sort((a, b) => a - b);
        const clustered = [];
        let currentCluster = [levels[0]];

        for (let i = 1; i < levels.length; i++) {
            if ((levels[i] - currentCluster[0]) / currentCluster[0] < 0.01) {
                currentCluster.push(levels[i]);
            } else {
                clustered.push(currentCluster.reduce((a, b) => a + b) / currentCluster.length);
                currentCluster = [levels[i]];
            }
        }
        clustered.push(currentCluster.reduce((a, b) => a + b) / currentCluster.length);
        return clustered;
    };

    return {
        support: clusterLevels(support).slice(-3),  // Top 3 support levels
        resistance: clusterLevels(resistance).slice(-3)  // Top 3 resistance levels
    };
}

// ==================== VOLUME PROFILE ANALYSIS ====================

function analyzeVolumeProfile(bars, period = 20) {
    if (bars.length < period) return { trend: 'neutral', vpoc: 0, strength: 0 };

    const recentBars = bars.slice(-period);
    const volumes = recentBars.map(b => b.v);
    const avgVolume = volumes.reduce((a, b) => a + b, 0) / period;
    const currentVolume = volumes[volumes.length - 1];

    // Volume-weighted average price (VWAP)
    let cumulativeVolPrice = 0;
    let cumulativeVol = 0;

    for (const bar of recentBars) {
        const typicalPrice = (bar.h + bar.l + bar.c) / 3;
        cumulativeVolPrice += typicalPrice * bar.v;
        cumulativeVol += bar.v;
    }

    const vpoc = cumulativeVol > 0 ? cumulativeVolPrice / cumulativeVol : 0;
    const volumeRatio = currentVolume / avgVolume;

    // Volume trend
    const firstHalfVol = volumes.slice(0, period / 2).reduce((a, b) => a + b, 0);
    const secondHalfVol = volumes.slice(period / 2).reduce((a, b) => a + b, 0);
    const volTrend = secondHalfVol > firstHalfVol * 1.2 ? 'increasing' :
                     secondHalfVol < firstHalfVol * 0.8 ? 'decreasing' : 'stable';

    return {
        trend: volTrend,
        vpoc: vpoc,
        strength: volumeRatio,
        avgVolume: avgVolume
    };
}

// ==================== MULTI-TIMEFRAME TREND ANALYSIS ====================

async function getMultiTimeframeTrend(symbol) {
    try {
        // Fetch 5min, 15min, and 1hour bars
        const [bars5m, bars15m, bars1h] = await Promise.all([
            axios.get(`https://data.alpaca.markets/v2/stocks/${symbol}/bars?timeframe=5Min&limit=50`, { headers: alpacaHeaders }),
            axios.get(`https://data.alpaca.markets/v2/stocks/${symbol}/bars?timeframe=15Min&limit=50`, { headers: alpacaHeaders }),
            axios.get(`https://data.alpaca.markets/v2/stocks/${symbol}/bars?timeframe=1Hour&limit=50`, { headers: alpacaHeaders })
        ]);

        const analyzeTrend = (bars) => {
            if (!bars || bars.length < 20) return 'neutral';
            const closes = bars.map(b => b.c);
            const ema9 = calculateEMA(closes, 9);
            const ema21 = calculateEMA(closes, 21);
            const currentPrice = closes[closes.length - 1];

            if (currentPrice > ema9 && ema9 > ema21) return 'bullish';
            if (currentPrice < ema9 && ema9 < ema21) return 'bearish';
            return 'neutral';
        };

        return {
            tf5m: analyzeTrend(bars5m.data.bars),
            tf15m: analyzeTrend(bars15m.data.bars),
            tf1h: analyzeTrend(bars1h.data.bars)
        };
    } catch (error) {
        console.log(`Multi-timeframe analysis failed for ${symbol}: ${error.message}`);
        return { tf5m: 'neutral', tf15m: 'neutral', tf1h: 'neutral' };
    }
}

// ==================== ML PATTERN RECOGNITION ====================

function detectPatterns(bars) {
    if (bars.length < 5) return [];

    const patterns = [];
    const recentBars = bars.slice(-5);

    // Higher highs and higher lows (uptrend pattern)
    const highs = recentBars.map(b => b.h);
    const lows = recentBars.map(b => b.l);

    const isHigherHighs = highs[4] > highs[3] && highs[3] > highs[2];
    const isHigherLows = lows[4] > lows[3] && lows[3] > lows[2];

    if (isHigherHighs && isHigherLows) {
        patterns.push({ name: 'uptrend', confidence: 0.8 });
    }

    // Bullish engulfing
    const prev = recentBars[recentBars.length - 2];
    const curr = recentBars[recentBars.length - 1];

    if (prev.c < prev.o && curr.c > curr.o &&
        curr.o < prev.c && curr.c > prev.o) {
        patterns.push({ name: 'bullish_engulfing', confidence: 0.75 });
    }

    // Morning star (3-candle reversal)
    if (recentBars.length >= 3) {
        const first = recentBars[recentBars.length - 3];
        const middle = recentBars[recentBars.length - 2];
        const last = recentBars[recentBars.length - 1];

        const isMorningStar =
            first.c < first.o &&  // Bearish first candle
            Math.abs(middle.c - middle.o) < (first.o - first.c) * 0.3 &&  // Small body
            last.c > last.o &&  // Bullish last candle
            last.c > (first.o + first.c) / 2;  // Closes above midpoint of first

        if (isMorningStar) {
            patterns.push({ name: 'morning_star', confidence: 0.85 });
        }
    }

    return patterns;
}

// ==================== TREND PREDICTION SCORE ====================

function calculateTrendPredictionScore(indicators, patterns, multiTF, srLevels, currentPrice) {
    let score = 0;
    const details = [];

    // 1. MACD Signal (30 points)
    if (indicators.macd) {
        if (indicators.macd.macd > indicators.macd.signal &&
            indicators.macd.histogram > 0 &&
            indicators.macd.histogram > indicators.macd.prevHistogram) {
            score += 30;
            details.push('MACD bullish crossover');
        } else if (indicators.macd.macd > indicators.macd.signal) {
            score += 15;
            details.push('MACD above signal');
        }
    }

    // 2. ADX Trend Strength (25 points)
    if (indicators.adx.adx > 25 && indicators.adx.plusDI > indicators.adx.minusDI) {
        score += 25;
        details.push('Strong uptrend (ADX > 25)');
    } else if (indicators.adx.adx > 20 && indicators.adx.plusDI > indicators.adx.minusDI) {
        score += 15;
        details.push('Moderate uptrend');
    }

    // 3. EMA Alignment (20 points)
    if (currentPrice > indicators.ema9 && indicators.ema9 > indicators.ema21 && indicators.ema21 > indicators.ema50) {
        score += 20;
        details.push('Perfect EMA alignment');
    } else if (currentPrice > indicators.ema21) {
        score += 10;
        details.push('Price above EMA21');
    }

    // 4. RSI Optimal Zone (15 points)
    if (indicators.rsi > 50 && indicators.rsi < 70) {
        score += 15;
        details.push('RSI in bullish zone');
    } else if (indicators.rsi > 40 && indicators.rsi < 80) {
        score += 7;
    }

    // 5. Stochastic (10 points)
    if (indicators.stoch.k > 20 && indicators.stoch.k < 80 && indicators.stoch.k > indicators.stoch.d) {
        score += 10;
        details.push('Stochastic bullish');
    }

    // 6. CCI (10 points)
    if (indicators.cci > 0 && indicators.cci < 200) {
        score += 10;
        details.push('CCI positive momentum');
    }

    // 7. Volume Confirmation (10 points)
    if (indicators.volumeProfile.strength > 1.5) {
        score += 10;
        details.push('High volume confirmation');
    } else if (indicators.volumeProfile.strength > 1.2) {
        score += 5;
    }

    // 8. OBV Trend (10 points)
    if (indicators.obv > 0) {
        score += 10;
        details.push('Positive OBV');
    }

    // 9. Multi-Timeframe Alignment (15 points)
    const bullishTimeframes = [multiTF.tf5m, multiTF.tf15m, multiTF.tf1h].filter(tf => tf === 'bullish').length;
    score += bullishTimeframes * 5;
    if (bullishTimeframes >= 2) {
        details.push(`${bullishTimeframes}/3 timeframes bullish`);
    }

    // 10. Pattern Recognition (15 points)
    const patternBonus = patterns.reduce((sum, p) => sum + (p.confidence * 15), 0);
    score += Math.min(patternBonus, 15);
    if (patterns.length > 0) {
        details.push(`Patterns: ${patterns.map(p => p.name).join(', ')}`);
    }

    // 11. Support/Resistance Proximity (10 points)
    // Bullish if near support or broke resistance
    const nearSupport = srLevels.support.some(s => Math.abs(currentPrice - s) / currentPrice < 0.02);
    const aboveResistance = srLevels.resistance.every(r => currentPrice > r * 1.01);

    if (aboveResistance) {
        score += 10;
        details.push('Broke resistance');
    } else if (nearSupport) {
        score += 5;
        details.push('Near support');
    }

    return {
        score: Math.min(score, 180),  // Cap at 180
        normalizedScore: Math.min((score / 180) * 100, 100),  // Convert to 0-100
        details: details
    };
}

