// ==================== HELPER FUNCTIONS ====================

function calculateATR(bars, period = 14) {
    if (bars.length < period + 1) return 0;

    const trValues = [];
    for (let i = 1; i < bars.length; i++) {
        const highLow = bars[i].h - bars[i].l;
        const highPrevClose = Math.abs(bars[i].h - bars[i - 1].c);
        const lowPrevClose = Math.abs(bars[i].l - bars[i - 1].c);
        trValues.push(Math.max(highLow, highPrevClose, lowPrevClose));
    }

    let atr = trValues.slice(0, period).reduce((a, b) => a + b, 0) / period;
    for (let i = period; i < trValues.length; i++) {
        atr = ((period - 1) * atr + trValues[i]) / period;
    }
    return atr;
}

function calculateRSI(prices, period = 14) {
    if (prices.length < period + 1) return 50;
    let gains = 0, losses = 0;
    for (let i = prices.length - period; i < prices.length; i++) {
        const change = prices[i] - prices[i - 1];
        if (change > 0) gains += change;
        else losses += Math.abs(change);
    }
    const avgGain = gains / period;
    const avgLoss = losses / period;
    const rs = avgGain / (avgLoss || 0.001);
    return 100 - (100 / (1 + rs));
}

function calculateEMA(prices, period) {
    if (prices.length < period) return null;
    const k = 2 / (period + 1);
    let ema = prices.slice(0, period).reduce((a, b) => a + b, 0) / period;
    for (let i = period; i < prices.length; i++) {
        ema = (prices[i] * k) + (ema * (1 - k));
    }
    return ema;
}

function calculateMACD(prices) {
    if (prices.length < 26) return null;

    const ema12 = calculateEMA(prices, 12);
    const ema26 = calculateEMA(prices, 26);

    if (!ema12 || !ema26) return null;

    const macd = ema12 - ema26;
    const signal = macd * 0.9; // Simplified

    return {
        macd: macd,
        signal: signal,
        histogram: macd - signal
    };
}

// ==================== WIN RATE TRACKING ====================

async function getWinRate() {
    try {
        // Fetch recent closed positions from Alpaca
        const ordersResponse = await axios.get(
            'https://paper-api.alpaca.markets/v2/orders?status=filled&limit=100',
            { headers: alpacaHeaders }
        );

        const orders = ordersResponse.data || [];

        // Group by symbol to find entry/exit pairs
        const trades = {};

        for (const order of orders) {
            const symbol = order.symbol;
            if (!trades[symbol]) trades[symbol] = [];
            trades[symbol].push(order);
        }

        let wins = 0;
        let losses = 0;

        for (const symbol in trades) {
            const symbolOrders = trades[symbol].sort((a, b) =>
                new Date(a.filled_at) - new Date(b.filled_at)
            );

            // Match buy/sell pairs
            for (let i = 0; i < symbolOrders.length - 1; i += 2) {
                if (symbolOrders[i].side === 'buy' && symbolOrders[i + 1].side === 'sell') {
                    const entryPrice = parseFloat(symbolOrders[i].filled_avg_price);
                    const exitPrice = parseFloat(symbolOrders[i + 1].filled_avg_price);

                    if (exitPrice > entryPrice) wins++;
                    else losses++;
                }
            }
        }

        const totalTrades = wins + losses;
        const winRate = totalTrades > 0 ? wins / totalTrades : 0.5;

        console.log(`Win Rate: ${(winRate * 100).toFixed(1)}% (${wins}W / ${losses}L)`);

        return {
            winRate: winRate,
            wins: wins,
            losses: losses,
            totalTrades: totalTrades
        };

    } catch (error) {
        console.log('Win rate calculation failed, using default 50%');
        return { winRate: 0.5, wins: 0, losses: 0, totalTrades: 0 };
    }
}

