            // ==================== DYNAMIC STOP LOSS ====================

            // ATR-based stop: 2x ATR for normal volatility, 3x for high volatility
            const atrMultiplier = volatilityPct > 3 ? 3 : 2;
            const dynamicStopLoss = (atr * atrMultiplier / currentPrice) * 100;

            // Dynamic take profit: 1.5x to 2.5x stop loss based on trend strength
            const riskRewardRatio = rsi > 60 && macd && macd.histogram > 0 ? 2.5 : 1.5;
